<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Throwable;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetFilter;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetCursor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetAttributes;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\List\SnippetAssetListUsecase;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\MagicLinkService;

class SnippetAssetListController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SnippetAssetListUsecase $listUsecase,
        private readonly Context $context,
        private readonly MagicLinkService $links,
    ) {
    }
    #[OA\Get(
        path: "/api/document/snippet-asset",
        tags: ["Snippet asset"],
        description:"Create",
        responses: [
        new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetAssetApiListDTO")),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function list(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("List Snippet asset");
        $span = $this->startSpan("List Snippet asset");
        try {
            $params = $request->getQueryParams();
            $filter = new SnippetAssetFilter(
                uids: isset($params['uid']) ? [$params['uid']] : (isset($params['uids']) ? explode(',', $params['uids']) : null),
                search: $params['search'] ?? null,
                code: $params['code'] ?? null,
                snippet: isset($params['snippet']) ? new SnippetRef($params['snippet']) : null,
                snippets: isset($params['snippets']) ? explode(",", $params['snippets']) : null,
            );
            $cursor = new SnippetAssetCursor(
                limit: (int)($params['limit'] ?? 100),
                sinceUid: $params['since-uid'] ?? null,
                sinceCode: $params['since-code'] ?? null,
                order: isset($params['order']) ? $this->extractOrder(explode(',', $params['order'])) : null,
            );
            $result = $this->listUsecase->list($filter, $cursor);
            $value = ['items' => array_map(fn (SnippetAssetAttributes $item): SnippetAssetApiDTO => $this->mapSnippetAsset($request, $item), $result->values())];
            $nextLink = $this->nextLink($result->cursor(), $params);
            if (null !== $nextLink) {
                $value['next'] = "?{$nextLink}";
            }
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
              ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function extractOrder(array $order): array
    {
        $this->logDebug("Extract order for Snippet asset");
        $span = $this->startSpan("Extract order for Snippet asset");
        try {
            $mapped = [];
            foreach ($order as $ord) {
                if ($ord === 'code-asc') {
                    $mapped[] = 'codeAsc';
                }
                if ($ord === 'code-desc') {
                    $mapped[] = 'codeDesc';
                }
            }
            return $mapped;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function nextLink(?SnippetAssetCursor $value, array $params): ?string
    {
        $this->logDebug("Check generic allow for Snippet asset");
        $span = $this->startSpan("Generic allow for Snippet asset");
        try {
            if (!$value) {
                return null;
            }
            $link = [];
            if (isset($params['limit'])) {
                $link['limit'] = 'limit=' . $params['limit'];
            }
            $sinceUid = $value->sinceUid();
            if (null !== $sinceUid) {
                $link['since-uid'] = 'since-uid=' . urlencode($sinceUid);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-ASC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            $sinceCode = $value->sinceCode();
            if (null !== $sinceCode &&  false !== strpos($params['order'] ?? '', 'CODE-DESC')) {
                $link['since-code'] = 'since-code=' . urlencode($sinceCode);
            }
            return implode('&', $link);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapSnippetAsset(ServerRequestInterface $request, SnippetAssetAttributes $value): SnippetAssetApiDTO
    {
        $this->logDebug("Map entity to output dto for Snippet asset");
        $span = $this->startSpan("Map entity to output dto for Snippet asset");
        try {
            $snippet = $value->getSnippet();
            $dto = new SnippetAssetApiDTO();
            $dto->uid = $value->getUid();
            $dto->snippet = $snippet ? ['$ref' => $snippet->uid()] : null;
            $dto->code = $value->getCode();
            $dto->type = $value->getType();
            if (null !== $value->getContent()) {
                $url = $this->context->getBaseUrl() . '/api/document/snippet-asset/' . ($value->getUid() ?? '-'). '/content';
                $dto->content = $this->links->create($url, $request);
            }
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
